package com.andye.warmod.phalanx;import com.andye.warmod.antiair.AntiAirFlightControllerManager;import com.andye.warmod.warhead.IncomingWarheadRegistry;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;import java.util.UUID;
public final class PointDefenceInterceptionService{private PointDefenceInterceptionService(){}public static boolean intercept(ServerLevel level,PhalanxTargetSnapshot target,UUID bullet,Vec3 hit){if(target.kind()==PhalanxTargetKind.MK_I_FALLBACK)return AntiAirFlightControllerManager.cancelForPointDefence(level,target.targetId(),bullet,hit);return IncomingWarheadRegistry.getByWarheadId(level,target.targetId()).map(w->w.cancelForPointDefence(level,bullet,hit)).orElse(false);}}
